"use client";

import { type CodeBlockProps, CodeBlock as CodeBlockRoot } from "./code-block";
import { CodeBlockContent, type CodeBlockContentProps } from "./code-block-content";
import type { CodeBlockChrome, CodeBlockVariant } from "./code-block-context";
import { CodeBlockCopyButton, type CodeBlockCopyButtonProps } from "./code-block-copy-button";
import { CodeBlockHeader, type CodeBlockHeaderProps } from "./code-block-header";
import { CodeBlockLabel, type CodeBlockLabelProps } from "./code-block-label";
import {
  CodeBlockLine,
  type CodeBlockLineProps,
  type CodeBlockLineState,
  type CodeBlockToken,
} from "./code-block-line";
import { InlineCode } from "./inline-code";

const CodeBlock = Object.assign(CodeBlockRoot, {
  Content: CodeBlockContent,
  Header: CodeBlockHeader,
  Label: CodeBlockLabel,
  Line: CodeBlockLine,
  CopyButton: CodeBlockCopyButton,
  Inline: InlineCode,
});

export {
  CodeBlock,
  CodeBlockContent,
  CodeBlockHeader,
  CodeBlockLabel,
  CodeBlockLine,
  CodeBlockCopyButton,
  InlineCode,
  type CodeBlockProps,
  type CodeBlockContentProps,
  type CodeBlockHeaderProps,
  type CodeBlockLabelProps,
  type CodeBlockLineProps,
  type CodeBlockCopyButtonProps,
  type CodeBlockToken,
  type CodeBlockLineState,
  type CodeBlockVariant,
  type CodeBlockChrome,
};

"use client";

import { type ComponentProps, useCallback, useMemo, useRef, useState } from "react";
import {
  type CodeBlockChrome,
  CodeBlockProvider,
  type CodeBlockVariant,
} from "./code-block-context";

/** Props for code block. */
export interface CodeBlockProps extends Omit<ComponentProps<"figure">, "children"> {
  /**
   * Visual variant. "hairline" (default) is a soft-bordered block with a filename header.
   * "bare" removes chrome and renders a 2px left rule that turns accent on hover; the header is
   * suppressed. "terminal" centers the title in the header - use for shell output. The pane
   * strip is opt-in for every variant via the `chrome` prop.
   */
  variant?: CodeBlockVariant;
  /**
   * Language identifier exposed as data-language and used in the default aria-label
   * ("{language} code").
   */
  language?: string;
  /**
   * Optional accessible name when no <CodeBlock.Label> is rendered. Falls back to "{language}
   * code" or "Code block".
   */
  label?: string;
  /**
   * Decorative chrome in the header strip. "none" (default) leaves the header to its label and
   * actions. "dots" renders a three-mark pane strip on the left edge and reserves
   * symmetric padding so a centered label stays balanced.
   */
  chrome?: CodeBlockChrome;
  /** Header and Content subparts. */
  children?: ComponentProps<"figure">["children"];
}

function resolveAriaName(
  props: { "aria-label"?: string; "aria-labelledby"?: string },
  renderedLabelId: string | null,
  fallbackName: string,
): { "aria-label"?: string; "aria-labelledby"?: string } {
  if (props["aria-label"] !== undefined || props["aria-labelledby"] !== undefined) {
    return {
      "aria-label": props["aria-label"],
      "aria-labelledby": props["aria-labelledby"],
    };
  }
  if (renderedLabelId) return { "aria-labelledby": renderedLabelId };
  return { "aria-label": fallbackName };
}

/** Root <figure>. */
export function CodeBlock({
  variant,
  language,
  label,
  chrome,
  className,
  children,
  ref,
  ...props
}: CodeBlockProps) {
  const resolvedVariant: CodeBlockVariant = variant ?? "hairline";
  const resolvedChrome: CodeBlockChrome = chrome ?? "none";
  const [renderedLabelId, setRenderedLabelId] = useState<string | null>(null);
  // Keyed by symbol so a remounting Label's cleanup cannot clear the id its own
  // re-registration just set (StrictMode, or two Labels swapping); the first
  // surviving registration wins.
  const labelRegistrationsRef = useRef(new Map<symbol, string>());

  const fallbackName = label ?? (language ? `${language} code` : "Code block");
  const ariaProps = resolveAriaName(props, renderedLabelId, fallbackName);

  const registerLabel = useCallback((id: string) => {
    const token = Symbol("code-block-label");
    const registrations = labelRegistrationsRef.current;
    registrations.set(token, id);
    setRenderedLabelId(registrations.values().next().value ?? null);

    return () => {
      registrations.delete(token);
      setRenderedLabelId(registrations.values().next().value ?? null);
    };
  }, []);

  const contextValue = useMemo(
    () => ({
      variant: resolvedVariant,
      chrome: resolvedChrome,
      registerLabel,
      ariaLabel: ariaProps["aria-label"],
      ariaLabelledBy: ariaProps["aria-labelledby"],
    }),
    [
      resolvedVariant,
      resolvedChrome,
      registerLabel,
      ariaProps["aria-label"],
      ariaProps["aria-labelledby"],
    ],
  );

  return (
    <CodeBlockProvider value={contextValue}>
      <figure
        ref={ref}
        data-slot="code-block"
        data-variant={resolvedVariant}
        data-chrome={resolvedChrome}
        data-language={language}
        className={className}
        {...ariaProps}
        {...props}
      >
        {resolvedChrome === "dots" ? (
          <span aria-hidden="true" data-slot="code-block-dots">
            <span />
            <span />
            <span />
          </span>
        ) : null}
        {children}
      </figure>
    </CodeBlockProvider>
  );
}

"use client";

import { createContext, useContext } from "react";

/** Allowed code block variant values. */
export type CodeBlockVariant = "hairline" | "bare" | "terminal";

/** Decorative header chrome options. */
export type CodeBlockChrome = "dots" | "none";

/** Context value shared by code block. */
export interface CodeBlockContextValue {
  /**
   * Visual variant. "hairline" (default) is a soft-bordered block with a filename header.
   * "bare" removes chrome and renders a 2px left rule that turns accent on hover; the header is
   * suppressed. "terminal" centers the title in the header - use for shell output. The pane
   * strip is opt-in for every variant via the `chrome` prop.
   */
  variant: CodeBlockVariant;
  /**
   * Decorative chrome in the header strip. "none" (default) leaves the header to its label and
   * actions. "dots" renders a three-mark pane strip on the left edge and reserves
   * symmetric padding so a centered label stays balanced.
   */
  chrome: CodeBlockChrome;
  /** Registers the id of a label that actually rendered. */
  registerLabel: (id: string) => () => void;
  /** Resolved accessible label for the code block. */
  ariaLabel: string | undefined;
  ariaLabelledBy: string | undefined;
}

const CodeBlockContext = createContext<CodeBlockContextValue | null>(null);

export const CodeBlockProvider = CodeBlockContext.Provider;

export function useRequiredCodeBlockContext(consumerName: string): CodeBlockContextValue {
  const context = useContext(CodeBlockContext);
  if (!context) {
    throw new Error(`${consumerName} must be used inside <CodeBlock>`);
  }
  return context;
}

"use client";

import { Children, type ComponentProps, type CSSProperties } from "react";
import { ScrollArea } from "../scroll-area/scroll-area";
import { useRequiredCodeBlockContext } from "./code-block-context";
import { CodeBlockLine } from "./code-block-line";

/** Props for code block content. */
export interface CodeBlockContentProps extends ComponentProps<"div"> {
  /** Auto-split mode only. Renders a line-number gutter for string children. */
  showLineNumbers?: boolean;
}

/** Scrollable <pre> body (auto-split or composed) */
export function CodeBlockContent({
  showLineNumbers = true,
  className,
  children,
  ref,
  "aria-label": ariaLabel,
  "aria-labelledby": ariaLabelledBy,
  ...props
}: CodeBlockContentProps) {
  const context = useRequiredCodeBlockContext("CodeBlock.Content");
  const hasExplicitName = ariaLabel !== undefined || ariaLabelledBy !== undefined;
  const resolvedLabel = hasExplicitName ? ariaLabel : context.ariaLabel;
  const resolvedLabelledBy = hasExplicitName ? ariaLabelledBy : context.ariaLabelledBy;

  const lines = typeof children === "string" ? children.split("\n") : null;
  const lineCount = lines ? lines.length : Children.count(children);
  const gutterWidth = Math.max(String(lineCount).length, 2);

  return (
    <ScrollArea
      orientation="both"
      ref={ref}
      aria-label={resolvedLabel}
      aria-labelledby={resolvedLabelledBy}
      className={className}
      {...props}
    >
      <pre
        data-slot="code-block-content"
        style={{ "--code-block-line-number-w": `${gutterWidth}ch` } as CSSProperties}
      >
        {lines
          ? lines.map((line, i) => (
              // biome-ignore lint/suspicious/noArrayIndexKey: code lines render in fixed source order and are never reordered; the line index is the stable identity (line content can repeat).
              <CodeBlockLine key={i} number={showLineNumbers ? i + 1 : undefined} content={line} />
            ))
          : children}
      </pre>
    </ScrollArea>
  );
}

"use client";

import type { ComponentProps } from "react";
import { useRequiredCodeBlockContext } from "./code-block-context";

/** Props for code block header. */
export type CodeBlockHeaderProps = ComponentProps<"div">;

/** Header row (filename + actions); hidden in bare variant. */
export function CodeBlockHeader({ className, ref, ...props }: CodeBlockHeaderProps) {
  const context = useRequiredCodeBlockContext("CodeBlock.Header");
  if (context.variant === "bare") return null;
  return <div ref={ref} data-slot="code-block-header" className={className} {...props} />;
}

"use client";

import { type ComponentProps, useId, useLayoutEffect } from "react";
import { useRequiredCodeBlockContext } from "./code-block-context";

/** Props for code block label. */
export type CodeBlockLabelProps = ComponentProps<"span">;

/** Filename label, wired to figure's accessible name. */
export function CodeBlockLabel({ id, className, children, ref, ...props }: CodeBlockLabelProps) {
  const context = useRequiredCodeBlockContext("CodeBlock.Label");
  const { registerLabel } = context;
  const implicitId = useId();
  const resolvedId = id ?? implicitId;

  useLayoutEffect(() => registerLabel(resolvedId), [registerLabel, resolvedId]);

  return (
    <span ref={ref} id={resolvedId} data-slot="code-block-label" className={className} {...props}>
      {children}
    </span>
  );
}

import type { ComponentProps, ReactNode } from "react";

/** Token rendered by CodeBlockLine when using the `content` token array. */
export interface CodeBlockToken {
  /** Text content. */
  text: string;
  /** Color token. */
  color?: string;
  /** Additional class names merged onto the rendered element. */
  className?: string;
}

/** Allowed code block line state values. */
export type CodeBlockLineState = "highlight" | "added" | "removed";

/** Props for code block line. */
export interface CodeBlockLineProps extends Omit<ComponentProps<"span">, "content" | "children"> {
  /** Line number rendered in the gutter. Omit to hide the gutter for this line. */
  number?: number;
  /**
   * Line content. Either a plain string or an array of tokens for syntax coloring. Ignored when
   * `children` is provided.
   */
  content?: string | CodeBlockToken[];
  /**
   * Pre-rendered line body (e.g. highlighted React elements). Takes precedence over `content`
   * and renders inside the <code> element.
   */
  children?: ReactNode;
  /**
   * Per-line visual state. "highlight" tints the row; "added"/"removed" render gutter sign
   * characters (+/−), color tint, and an sr-only "Added: "/"Removed: " prefix for assistive
   * tech.
   */
  state?: CodeBlockLineState;
  /** Screen-reader prefix for an added diff line. Defaults to "Added: ". */
  addedLineLabel?: string;
  /** Screen-reader prefix for a removed diff line. Defaults to "Removed: ". */
  removedLineLabel?: string;
}

const BLANK_SIGN = " ";

function signCharacter(state: CodeBlockLineState | undefined): string {
  if (state === "added") return "+";
  if (state === "removed") return "−";
  return BLANK_SIGN;
}

function renderContent(content: string | CodeBlockToken[] | undefined): ReactNode {
  if (content == null) return null;
  if (typeof content === "string") return content;
  return content.map((token, i) => (
    // biome-ignore lint/suspicious/noArrayIndexKey: syntax tokens render in fixed left-to-right order within a line and are never reordered; the token index is the stable identity.
    <span key={i} style={{ color: token.color }} className={token.className}>
      {token.text}
    </span>
  ));
}

/** Single line with optional gutter, diff state, and token coloring. */
export function CodeBlockLine({
  number,
  content,
  children,
  state,
  className,
  addedLineLabel = "Added: ",
  removedLineLabel = "Removed: ",
  ref,
  ...props
}: CodeBlockLineProps) {
  const isDiffLine = state === "added" || state === "removed";
  return (
    <span ref={ref} data-slot="code-block-line" data-state={state} className={className} {...props}>
      {number != null ? (
        <span aria-hidden="true" data-slot="code-block-line-number">
          {number}
        </span>
      ) : null}
      <span aria-hidden="true" data-slot="code-block-line-sign">
        {signCharacter(state)}
      </span>
      {isDiffLine ? (
        <span className="sr-only">{state === "added" ? addedLineLabel : removedLineLabel}</span>
      ) : null}
      <code>{children ?? renderContent(content)}</code>
    </span>
  );
}

"use client";

import type { ComponentProps, MouseEvent, ReactNode } from "react";
import { useCopyToClipboard } from "@/hooks/use-copy-to-clipboard";
import { hasAccessibleTextContent } from "@/lib/accessible-text";

/** Props for code block copy button. */
export interface CodeBlockCopyButtonProps
  extends Omit<ComponentProps<"button">, "children" | "onCopy"> {
  /** Text copied to the clipboard on click. */
  source: string;
  /** Accessible label for the button (overrideable for localization). */
  copyLabel?: string;
  /** Status message announced via aria-live after a successful copy. */
  copiedMessage?: string;
  /** Status message announced via aria-live after a failed copy. */
  copyFailedMessage?: string;
  /** Optional button content or a render function that receives the copy state. */
  children?: ((state: "idle" | "copied" | "failed") => ReactNode) | ReactNode;
  /** Called after a successful clipboard write. */
  onCopy?: (source: string) => void;
  /** Called when the clipboard write fails or the API is unavailable. */
  onCopyError?: (error: unknown) => void;
}

function ClipboardIcon({ state }: { state: "idle" | "copied" | "failed" }) {
  if (state === "copied") {
    return (
      <svg
        aria-hidden="true"
        viewBox="0 0 16 16"
        width="14"
        height="14"
        fill="none"
        stroke="currentColor"
        strokeWidth="1.5"
        strokeLinecap="square"
        strokeLinejoin="miter"
      >
        <path d="M3 8.5l3 3 7-7" />
      </svg>
    );
  }
  return (
    <svg
      aria-hidden="true"
      viewBox="0 0 16 16"
      width="14"
      height="14"
      fill="none"
      stroke="currentColor"
      strokeWidth="1.5"
      strokeLinecap="square"
      strokeLinejoin="miter"
    >
      <rect x="5" y="2.5" width="6" height="2" />
      <rect x="3.5" y="4.5" width="9" height="9" />
    </svg>
  );
}

/** Optional copy-to-clipboard button. */
export function CodeBlockCopyButton({
  source,
  copyLabel = "Copy code to clipboard",
  copiedMessage = "Copied",
  copyFailedMessage = "Copy failed",
  className,
  children,
  onClick,
  onCopy,
  onCopyError,
  "aria-label": ariaLabel,
  "aria-labelledby": ariaLabelledBy,
  ref,
  ...props
}: CodeBlockCopyButtonProps) {
  const { status, copy } = useCopyToClipboard({ onCopy, onError: onCopyError });
  const state = status;

  let liveMessage = "";
  if (state === "copied") liveMessage = copiedMessage;
  else if (state === "failed") liveMessage = copyFailedMessage;

  const handleClick = async (event: MouseEvent<HTMLButtonElement>) => {
    onClick?.(event);
    if (event.defaultPrevented) return;
    await copy(source);
  };

  const renderedChildren =
    typeof children === "function"
      ? children(state)
      : (children ?? <ClipboardIcon state={state} />);
  const fallbackLabel =
    ariaLabel || ariaLabelledBy || hasAccessibleTextContent(renderedChildren)
      ? undefined
      : copyLabel;

  return (
    <>
      <button
        ref={ref}
        type="button"
        data-slot="code-block-copy-button"
        data-state={state}
        aria-label={ariaLabel || fallbackLabel}
        aria-labelledby={ariaLabelledBy}
        className={className}
        onClick={handleClick}
        {...props}
      >
        {renderedChildren}
      </button>
      <span aria-live="polite" className="sr-only">
        {liveMessage}
      </span>
    </>
  );
}

import type { ComponentProps } from "react";
import { cn } from "@/lib/utils";

export function InlineCode({ className, ...props }: ComponentProps<"code">) {
  return (
    <code
      className={cn(
        "bg-secondary text-foreground px-1.5 py-0.5 text-xs font-mono rounded-sm",
        className,
      )}
      {...props}
    />
  );
}
